      setStatus("error");
    }
  }, []);

  return {
    status, address, apiVersion, network, error,
    connect,
    disconnect: () => { setAddress(null); setNetwork(null); setStatus("ready"); setError(null); },
    redetect: () => setTick((n) => n + 1),
  };
}
