              <span className="font-mono">{expectedNetwork}</span>. Switch networks inside Lace.
            </p>
          )}
        </div>
      )}

      {w.status === "error" && (
        <div className="space-y-2">
          <p className="text-sm opacity-80">{w.error ?? "Something went wrong."}</p>
          <div className="flex gap-3 flex-wrap">
